import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.map.js";
import { computed, onMounted, ref, onUnmounted } from 'vue';
import { useStore } from 'vuex';
import { useRouter } from 'vue-router';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import axios from 'axios';
import DOMPurify from 'dompurify';
export default {
  name: 'UserPage',
  setup() {
    const store = useStore();
    const router = useRouter();
    const contentRef = ref(null);
    const isUserInfoOpen = ref(false);
    const activeTab = ref('published');
    const publishedMoments = ref([]);
    const likedMoments = ref([]);
    const loading = ref(false);
    const showImagePreview = ref(false);
    const currentPreviewImage = ref('');
    const isRefreshing = ref(false);
    const pullDistance = ref(0);
    const pullState = ref('pull'); // pull, release, refreshing
    const showBottomTip = ref(false);
    const hasMoreData = ref(true);
    const page = ref(1);
    const pageSize = ref(10);
    const user = computed(() => store.state.user);
    const displayName = computed(() => user.value?.username || user.value?.phone || user.value?.email || '未登录');
    const pullStateText = computed(() => {
      switch (pullState.value) {
        case 'pull':
          return '下拉刷新';
        case 'release':
          return '释放刷新';
        case 'refreshing':
          return '刷新中...';
        default:
          return '下拉刷新';
      }
    });

    // 处理头像路径
    const avatarUrl = computed(() => {
      if (user.value?.photo) {
        return `${API_CONFIG.BASE_URL}${user.value.photo}`;
      }
      return defaultAvatar;
    });

    // 工具函数
    const getFullUrl = path => {
      if (!path || path === defaultAvatar) return path;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const formatTime = timestamp => {
      const date = new Date(timestamp);
      return `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-` + `${date.getDate().toString().padStart(2, '0')} ` + `${date.getHours().toString().padStart(2, '0')}:` + `${date.getMinutes().toString().padStart(2, '0')}`;
    };
    const getTimeAgo = timestamp => {
      const now = Date.now();
      const diff = now - new Date(timestamp).getTime();
      const minutes = Math.floor(diff / 60000);
      const hours = Math.floor(minutes / 60);
      const days = Math.floor(hours / 24);
      if (minutes < 1) return '刚刚';
      if (minutes < 60) return `${minutes}分钟前`;
      if (hours < 24) return `${hours}小时前`;
      return `${days}天前`;
    };
    const sanitizeHtml = html => DOMPurify.sanitize(html);
    const openImagePreview = url => {
      currentPreviewImage.value = url;
      showImagePreview.value = true;
      document.body.style.overflow = 'hidden'; // 防止背景滚动
    };
    const closeImagePreview = () => {
      showImagePreview.value = false;
      document.body.style.overflow = ''; // 恢复背景滚动
    };

    // 获取我发布的内容
    const fetchPublishedMoments = async (isRefresh = false, isLoadMore = false) => {
      if (isRefresh) {
        page.value = 1;
        hasMoreData.value = true;
      }
      if (isLoadMore && !hasMoreData.value) {
        return;
      }
      try {
        loading.value = true;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/article/user_moments`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          },
          params: {
            user_id: user.value.id,
            page: isLoadMore ? page.value : 1,
            pageSize: pageSize.value
          }
        });
        const newMoments = response.data.map(moment => ({
          ...moment,
          showCommentInput: false,
          commentInput: '',
          showAllComments: false,
          isLiked: moment.like_users?.includes(user.value.id) || false,
          stats: {
            likes: moment.likes || 0,
            comments: moment.comments?.length || 0
          }
        }));
        if (isRefresh) {
          publishedMoments.value = newMoments;
        } else if (isLoadMore) {
          publishedMoments.value = [...publishedMoments.value, ...newMoments];
          page.value += 1;

          // 如果没有更多数据，显示到底提示
          if (newMoments.length < pageSize.value) {
            hasMoreData.value = false;
            showBottomTip.value = true;

            // 3秒后隐藏提示
            setTimeout(() => {
              showBottomTip.value = false;
            }, 3000);
          }
        } else {
          publishedMoments.value = newMoments;
        }
      } catch (error) {
        console.error('获取发布内容失败:', error);
      } finally {
        loading.value = false;
        isRefreshing.value = false;
        pullDistance.value = 0;
        pullState.value = 'pull';
      }
    };

    // 获取我喜欢的内容
    const fetchLikedMoments = async (isRefresh = false, isLoadMore = false) => {
      if (isRefresh) {
        page.value = 1;
        hasMoreData.value = true;
      }
      if (isLoadMore && !hasMoreData.value) {
        return;
      }
      try {
        loading.value = true;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/article/liked_moments`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          },
          params: {
            user_id: user.value.id,
            page: isLoadMore ? page.value : 1,
            pageSize: pageSize.value
          }
        });
        const newMoments = response.data.map(moment => ({
          ...moment,
          showCommentInput: false,
          commentInput: '',
          showAllComments: false,
          isLiked: true,
          // 既然是我喜欢的内容，默认已点赞
          stats: {
            likes: moment.stats.likes || 0,
            comments: moment.stats.comments || 0
          }
        }));
        if (isRefresh) {
          likedMoments.value = newMoments;
        } else if (isLoadMore) {
          likedMoments.value = [...likedMoments.value, ...newMoments];
          page.value += 1;

          // 如果没有更多数据，显示到底提示
          if (newMoments.length < pageSize.value) {
            hasMoreData.value = false;
            showBottomTip.value = true;

            // 3秒后隐藏提示
            setTimeout(() => {
              showBottomTip.value = false;
            }, 3000);
          }
        } else {
          likedMoments.value = newMoments;
        }
      } catch (error) {
        console.error('获取喜欢内容失败:', error);
      } finally {
        loading.value = false;
        isRefreshing.value = false;
        pullDistance.value = 0;
        pullState.value = 'pull';
      }
    };

    // 切换标签
    const switchTab = tab => {
      activeTab.value = tab;
      if (tab === 'published' && publishedMoments.value.length === 0) {
        fetchPublishedMoments();
      } else if (tab === 'liked' && likedMoments.value.length === 0) {
        fetchLikedMoments();
      }
    };

    // 退出登录
    const logout = () => {
      store.dispatch('logout');
      router.push('/login');
    };

    // 跳转到用户详情页
    const goToUserDetail = () => {
      router.push('/user/detail');
    };

    // 切换用户信息子目录的展开状态
    const toggleUserInfo = () => {
      isUserInfoOpen.value = !isUserInfoOpen.value;
    };

    // 点赞功能
    const likeMoment = async momentId => {
      // 根据当前活动标签决定更新哪个数组
      const targetArray = activeTab.value === 'published' ? publishedMoments : likedMoments;
      const targetMoment = targetArray.value.find(moment => moment.id === momentId);
      if (!targetMoment) return;
      try {
        // 立即更新UI状态
        targetMoment.isLiked = !targetMoment.isLiked;
        targetMoment.stats.likes += targetMoment.isLiked ? 1 : -1;
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_moment`, {
          moment_id: momentId,
          user_id: user.value.id,
          is_like: targetMoment.isLiked
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          // 精确同步后端数据
          targetMoment.isLiked = response.data.is_liked;
          targetMoment.stats.likes = response.data.likes_count;
        }
      } catch (error) {
        // 回滚状态
        targetMoment.isLiked = !targetMoment.isLiked;
        targetMoment.stats.likes -= targetMoment.isLiked ? 1 : -1;
        console.error('点赞操作失败:', error);
      }
    };

    // 评论相关功能
    const toggleCommentInput = moment => {
      moment.showCommentInput = !moment.showCommentInput;
      moment.commentInput = '';
    };
    const postComment = async moment => {
      if (!moment.commentInput.trim()) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_comment`, {
          moment_id: moment.id,
          comment: moment.commentInput,
          comment_user_name: user.value.username,
          comment_user_id: user.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          // 在数组开头添加新评论
          moment.comments.unshift({
            id: response.data.id,
            comment: moment.commentInput,
            created_at: new Date().toISOString(),
            comment_user_name: user.value.username,
            comment_user_photo: user.value.photo,
            likes: 0,
            isLiked: false,
            replies: []
          });

          // 更新评论数量
          moment.stats.comments += 1;

          // 清空输入框并关闭
          moment.commentInput = '';
          moment.showCommentInput = false;
        }
      } catch (error) {
        console.error('评论失败:', error);
      }
    };
    const toggleReplyInput = comment => {
      comment.showReplyInput = !comment.showReplyInput;
      comment.replyInput = '';
    };
    const postReply = async (moment, comment) => {
      if (!comment.replyInput.trim()) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_reply`, {
          moment_id: moment.id,
          parent_comment_id: comment.id,
          comment: comment.replyInput,
          comment_user_id: user.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          comment.replies.push({
            ...response.data.reply,
            comment_user_name: user.value.username,
            comment_user_photo: user.value.photo
          });
          comment.replyInput = '';
          comment.showReplyInput = false;
        }
      } catch (error) {
        console.error('回复失败:', error);
      }
    };
    const likeComment = async (momentId, commentIndex) => {
      const targetArray = activeTab.value === 'published' ? publishedMoments : likedMoments;
      const moment = targetArray.value.find(m => m.id === momentId);
      const comment = moment?.comments[commentIndex];
      if (!comment) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_comment`, {
          comment_id: comment.id,
          user_id: user.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        comment.isLiked = response.data.is_liked;
        comment.likes = response.data.likes_count;
      } catch (error) {
        console.error('点赞失败:', error);
      }
    };

    // 辅助函数
    const visibleComments = moment => {
      return moment.showAllComments ? moment.comments : moment.comments.slice(0, 3);
    };

    // 处理下拉刷新
    let touchStartY = 0;
    let isDragging = false;
    const handleTouchStart = e => {
      if (contentRef.value.scrollTop <= 0) {
        touchStartY = e.touches[0].clientY;
        isDragging = true;
      }
    };
    const handleTouchMove = e => {
      if (!isDragging) return;
      const touchY = e.touches[0].clientY;
      const diff = touchY - touchStartY;
      if (diff > 0) {
        e.preventDefault(); // 阻止页面滚动

        // 计算下拉距离（减速效果）
        pullDistance.value = diff * 0.5;

        // 更新状态
        if (pullDistance.value > 50 && pullState.value !== 'refreshing') {
          pullState.value = 'release';
        } else if (pullDistance.value <= 50 && pullState.value !== 'refreshing') {
          pullState.value = 'pull';
        }
      }
    };
    const handleTouchEnd = () => {
      if (!isDragging) return;
      isDragging = false;
      if (pullDistance.value > 50 && pullState.value === 'release') {
        pullState.value = 'refreshing';
        isRefreshing.value = true;

        // 执行刷新操作
        if (activeTab.value === 'published') {
          fetchPublishedMoments(true);
        } else {
          fetchLikedMoments(true);
        }
      } else {
        // 重置
        pullDistance.value = 0;
        pullState.value = 'pull';
      }
    };

    // 处理滚动到底部加载更多
    const handleScroll = () => {
      if (!contentRef.value) return;
      const {
        scrollTop,
        scrollHeight,
        clientHeight
      } = contentRef.value;

      // 当滚动到距离底部100px时加载更多
      if (scrollTop + clientHeight >= scrollHeight - 100 && !loading.value && hasMoreData.value) {
        if (activeTab.value === 'published') {
          fetchPublishedMoments(false, true);
        } else {
          fetchLikedMoments(false, true);
        }
      }
    };

    // 页面加载时检查用户是否登录
    onMounted(() => {
      if (!store.state.user) {
        router.push('/login');
      } else {
        fetchPublishedMoments();
      }

      // 添加触摸事件监听
      contentRef.value.addEventListener('touchstart', handleTouchStart);
      contentRef.value.addEventListener('touchmove', handleTouchMove);
      contentRef.value.addEventListener('touchend', handleTouchEnd);
    });
    onUnmounted(() => {
      // 移除事件监听
      if (contentRef.value) {
        contentRef.value.removeEventListener('touchstart', handleTouchStart);
        contentRef.value.removeEventListener('touchmove', handleTouchMove);
        contentRef.value.removeEventListener('touchend', handleTouchEnd);
      }
    });
    return {
      user,
      displayName,
      avatarUrl,
      logout,
      goToUserDetail,
      isUserInfoOpen,
      toggleUserInfo,
      activeTab,
      switchTab,
      publishedMoments,
      likedMoments,
      getFullUrl,
      formatTime,
      getTimeAgo,
      sanitizeHtml,
      openImagePreview,
      closeImagePreview,
      showImagePreview,
      currentPreviewImage,
      defaultAvatar,
      likeMoment,
      toggleCommentInput,
      postComment,
      toggleReplyInput,
      postReply,
      likeComment,
      visibleComments,
      contentRef,
      isRefreshing,
      pullDistance,
      pullState,
      pullStateText,
      showBottomTip,
      handleScroll
    };
  }
};
